49	/// Result of evaluating the CocoaPods installation.
50	enum CocoaPodsStatus {
51	  /// iOS plugins will not work, installation required.
52	  notInstalled,
53	  /// iOS plugins might not work, upgrade recommended.
54	  unknownVersion,
55	  /// iOS plugins will not work, upgrade required.
56	  belowMinimumVersion,
57	  /// iOS plugins may not work in certain situations (Swift, static libraries),
58	  /// upgrade recommended.
59	  belowRecommendedVersion,
60	  /// Everything should be fine.
61	  recommended,
62	  /// iOS plugins will not work, re-install required.
63	  brokenInstall,
64	}
