66	/// Cocoapods is a dependency management solution for iOS and macOS applications.
67	///
68	/// Cocoapods is generally installed via ruby gems and interacted with via
69	/// the `pod` CLI command.
70	///
71	/// See also:
72	///   * https://cocoapods.org/ - the cocoapods website.
73	///   * https://flutter.dev/docs/get-started/install/macos#deploy-to-ios-devices - instructions for
74	///     installing iOS/macOS dependencies.
75	class CocoaPods {
76	  CocoaPods({
77	    @required FileSystem fileSystem,
78	    @required ProcessManager processManager,
79	    @required XcodeProjectInterpreter xcodeProjectInterpreter,
80	    @required Logger logger,
81	    @required Platform platform,
82	  }) : _fileSystem = fileSystem,
83	      _processManager = processManager,
84	      _xcodeProjectInterpreter = xcodeProjectInterpreter,
85	      _logger = logger,
86	      _platform = platform,
87	      _processUtils = ProcessUtils(processManager: processManager, logger: logger),
88	      _fileSystemUtils = FileSystemUtils(fileSystem: fileSystem, platform: platform);
89	
90	  final FileSystem _fileSystem;
91	  final ProcessManager _processManager;
92	  final FileSystemUtils _fileSystemUtils;
93	  final ProcessUtils _processUtils;
94	  final XcodeProjectInterpreter _xcodeProjectInterpreter;
95	  final Logger _logger;
96	  final Platform _platform;
97	
98	  Future<String> _versionText;
99	
100	  String get cocoaPodsMinimumVersion => '1.6.0';
101	  String get cocoaPodsRecommendedVersion => '1.9.0';
102	
103	  Future<bool> get isInstalled =>
104	    _processUtils.exitsHappy(<String>['which', 'pod']);
105	
106	  Future<String> get cocoaPodsVersionText {
107	    _versionText ??= _processUtils.run(
108	      <String>['pod', '--version'],
109	      environment: <String, String>{
110	        'LANG': 'en_US.UTF-8',
111	      },
112	    ).then<String>((RunResult result) {
113	      return result.exitCode == 0 ? result.stdout.trim() : null;
114	    }, onError: (dynamic _) => null);
115	    return _versionText;
116	  }
117	
118	  Future<CocoaPodsStatus> get evaluateCocoaPodsInstallation async {
119	    if (!(await isInstalled)) {
120	      return CocoaPodsStatus.notInstalled;
121	    }
122	    final String versionText = await cocoaPodsVersionText;
123	    if (versionText == null) {
124	      return CocoaPodsStatus.brokenInstall;
125	    }
126	    try {
127	      final Version installedVersion = Version.parse(versionText);
128	      if (installedVersion == null) {
129	        return CocoaPodsStatus.unknownVersion;
130	      }
131	      if (installedVersion < Version.parse(cocoaPodsMinimumVersion)) {
132	        return CocoaPodsStatus.belowMinimumVersion;
133	      }
134	      if (installedVersion < Version.parse(cocoaPodsRecommendedVersion)) {
135	        return CocoaPodsStatus.belowRecommendedVersion;
136	      }
137	      return CocoaPodsStatus.recommended;
138	    } on FormatException {
139	      return CocoaPodsStatus.notInstalled;
140	    }
141	  }
142	
143	  /// Whether CocoaPods ran 'pod setup' once where the costly pods' specs are
144	  /// cloned.
145	  ///
146	  /// Versions >= 1.8.0 do not require 'pod setup' and default to a CDN instead
147	  /// of a locally cloned repository.
148	  /// See http://blog.cocoapods.org/CocoaPods-1.8.0-beta/
149	  ///
150	  /// A user can override the default location via the CP_REPOS_DIR environment
151	  /// variable.
152	  ///
153	  /// See https://github.com/CocoaPods/CocoaPods/blob/master/lib/cocoapods/config.rb#L138
154	  /// for details of this variable.
155	  Future<bool> get isCocoaPodsInitialized async {
156	    final Version installedVersion = Version.parse(await cocoaPodsVersionText);
157	    if (installedVersion != null && installedVersion >= Version.parse('1.8.0')) {
158	      return true;
159	    }
160	    final String cocoapodsReposDir = _platform.environment['CP_REPOS_DIR']
161	      ?? _fileSystem.path.join(_fileSystemUtils.homeDirPath, '.cocoapods', 'repos');
162	    return _fileSystem.isDirectory(_fileSystem.path.join(cocoapodsReposDir, 'master'));
163	  }
164	
165	  Future<bool> processPods({
166	    @required XcodeBasedProject xcodeProject,
167	    // For backward compatibility with previously created Podfile only.
168	    @required String engineDir,
169	    bool dependenciesChanged = true,
170	  }) async {
171	    if (!xcodeProject.podfile.existsSync()) {
172	      throwToolExit('Podfile missing');
173	    }
174	    bool podsProcessed = false;
175	    if (_shouldRunPodInstall(xcodeProject, dependenciesChanged)) {
176	      if (!await _checkPodCondition()) {
177	        throwToolExit('CocoaPods not installed or not in valid state.');
178	      }
179	      await _runPodInstall(xcodeProject, engineDir);
180	      podsProcessed = true;
181	    }
182	    _warnIfPodfileOutOfDate(xcodeProject);
183	    return podsProcessed;
184	  }
