169	  xcodeBuildSettings.add('FLUTTER_APPLICATION_PATH=${globals.fs.path.normalize(project.directory.path)}');
170	
171	  // Relative to FLUTTER_APPLICATION_PATH, which is [Directory.current].
172	  if (targetOverride != null) {
173	    xcodeBuildSettings.add('FLUTTER_TARGET=$targetOverride');
174	  }
175	
176	  // The build outputs directory, relative to FLUTTER_APPLICATION_PATH.
177	  xcodeBuildSettings.add('FLUTTER_BUILD_DIR=${buildDirOverride ?? getBuildDirectory()}');
178	
179	  if (setSymroot) {
180	    xcodeBuildSettings.add('SYMROOT=\${SOURCE_ROOT}/../${getIosBuildDirectory()}');
181	  }
182	
183	  // iOS does not link on Flutter in any build phase. Add the linker flag.
184	  if (!useMacOSConfig) {
185	    xcodeBuildSettings.add(r'OTHER_LDFLAGS=$(inherited) -framework Flutter');
186	  }
