199	
200	  final String buildName = parsedBuildName(manifest: project.manifest, buildInfo: buildInfo) ?? '1.0.0';
201	  xcodeBuildSettings.add('FLUTTER_BUILD_NAME=$buildName');
202	
203	  final String buildNumber = parsedBuildNumber(manifest: project.manifest, buildInfo: buildInfo) ?? '1';
204	  xcodeBuildSettings.add('FLUTTER_BUILD_NUMBER=$buildNumber');
205	
206	  if (globals.artifacts is LocalEngineArtifacts) {
207	    final LocalEngineArtifacts localEngineArtifacts = globals.artifacts as LocalEngineArtifacts;
208	    final String engineOutPath = localEngineArtifacts.engineOutPath;
209	    xcodeBuildSettings.add('FLUTTER_ENGINE=${globals.fs.path.dirname(globals.fs.path.dirname(engineOutPath))}');
210	    xcodeBuildSettings.add('LOCAL_ENGINE=${globals.fs.path.basename(engineOutPath)}');
